attempts.proof:
apply HasSum_sum' (fun n => Real.exp (-↑r) * ↑r ^ n / ↑n.factorial) 1;
  refine (Real.exp (-↑r) * ∑' (fun n => ↑r ^ n / ↑n.factorial) 1).symm;
  have : ∑' (fun n => ↑r ^ n / ↑n.factorial) 1 = Real.exp ↑r := by
    rw [exp_add, Real.exp_zero];
    apply sum_exp_series;
  exact this;
  rw [this];
  rw [Real.exp_neg];
  exact rfl;
